const raw = $input.first().json;
// SePay gửi 'Authorization: Apikey <KEY>' (cấu hình trong dashboard SePay).
// Fail-open khi SEPAY_API_KEY rỗng (dev/mock) — điền key là khóa chặt.
const expected = $env.SEPAY_API_KEY || '';
const got = ((raw.headers || {})['authorization'] || '');
if (expected && got !== 'Apikey ' + expected) {
  return [{ json: { valid: false, error: 'Unauthorized: sai SePay API key' } }];
}
const b = (raw.body && typeof raw.body === 'object') ? raw.body : raw;
if (b.id === undefined || b.transferAmount === undefined) {
  return [{ json: { valid: false, error: 'Missing required fields: id, transferAmount' } }];
}
return [{ json: { valid: true, request_body: JSON.stringify({ id: b.id, gateway: b.gateway || null, transactionDate: b.transactionDate || null, content: b.content || '', transferAmount: b.transferAmount, transferType: b.transferType || 'in', accountNumber: b.accountNumber || null, referenceCode: b.referenceCode || null }) } }];

const inv = $input.first().json;
const pay = $('Match Payment (deterministic)').first().json;
const fmt = n => new Intl.NumberFormat('vi-VN').format(n);
let title, color, desc;
if (inv.status === 'issued') {
  title = '💰 Đã nhận thanh toán ' + pay.order_no + ' + HĐĐT ' + inv.invoice_no;
  color = 3066993;
  desc = 'CK ' + fmt(pay.amount) + ' đ qua ' + (pay.gateway || 'ngân hàng') + ' khớp đơn.\n' +
    '🧾 HĐĐT phát hành tự động — mã CQT: **' + inv.tax_authority_code + '**\n' +
    'VAT ' + inv.vat_rate + '%: ' + fmt(inv.vat_amount) + ' đ (trước thuế ' + fmt(inv.subtotal) + ' đ).';
} else if (inv.status === 'duplicate') {
  title = '💰 Thanh toán ' + pay.order_no + ' (HĐĐT đã có: ' + inv.invoice_no + ')';
  color = 3066993;
  desc = 'Đơn đã có hóa đơn hiệu lực — không phát hành trùng.';
} else {
  title = '⚠️ Thanh toán ' + pay.order_no + ' OK — HĐĐT VÀO HÀNG ĐỢI';
  color = 15105570;
  desc = (inv.reason || 'NCC HĐĐT lỗi') + '\nKhông để đơn thiếu hóa đơn — hàng đợi einvoice_pending #' + (inv.pending_id || '?') + ' sẽ phát hành lại.';
}
return [{ json: { notify_needed: true, notify_body: JSON.stringify({ channel: 'discord', title, color, description: desc }), resp: JSON.stringify({ status: 'ok', action: 'matched', order_no: pay.order_no, einvoice: inv.status, invoice_no: inv.invoice_no || null }) } }];

const d = $input.first().json;
const fmt = n => new Intl.NumberFormat('vi-VN').format(n);
let notify_needed = false, title = '', color = 15105570, desc = '';
if (d.action === 'review') {
  notify_needed = true;
  title = '🟠 CK cần ĐỐI SOÁT TAY';
  desc = (d.reason || '') + (d.suggested_order ? '\nGợi ý đơn khớp: **' + d.suggested_order + '**' : '') + '\nGiữ ở payment_pending — KHÔNG tự khớp tiền lệch.';
}
return [{ json: { notify_needed, notify_body: JSON.stringify({ channel: 'discord', title, color, description: desc }), resp: JSON.stringify({ status: 'ok', action: d.action, reason: d.reason || null, suggested_order: d.suggested_order || null }) } }];

// Lấy resp từ nhánh ĐÃ chạy (paid hoặc review) — tham chiếu node chưa chạy sẽ throw
let resp;
try { resp = $('Build Paid Notice').first().json.resp; } catch (e) { resp = $('Build Review Notice').first().json.resp; }
return [{ json: { resp } }];
